module meow_factor (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [4:0] char_0, char_1, char_2, char_3, char_4, char_5, char_6, char_7,\n    input wire [2:0] len,\n    output reg [3:0] result,\n    output reg done\n);\n\n// MEOW character codes (ASCII 'a' = 97)\nlocalparam CHAR_M = 5'd12;  // 'm' - 'a'\nlocalparam CHAR_E = 5'd4;   // 'e' - 'a'\nlocalparam CHAR_O = 5'd14;  // 'o' - 'a'\nlocalparam CHAR_W = 5'd22;  // 'w' - 'a'\n\n// State declarations\nlocalparam [1:0] IDLE    = 2'd0;\nlocalparam [1:0] INIT    = 2'd1;\nlocalparam [1:0] COMPUTE = 2'd2;\nlocalparam [1:0] FINISH  = 2'd3;\n\nreg [1:0] state;\nreg [2:0] char_idx;\nreg [1:0] meow_idx;\nreg [3:0] dp_prev [0:4];\nreg [3:0] dp_curr [0:4];\nreg [3:0] min_result;\nreg [4:0] current_char;\ninteger i;\n\n// Character selection\nalways @(*) begin\n    case(char_idx)\n        3'd0: current_char = char_0;\n        3'd1: current_char = char_1;\n        3'd2: current_char = char_2;\n        3'd3: current_char = char_3;\n        3'd4: current_char = char_4;\n        3'd5: current_char = char_5;\n        3'd6: current_char = char_6;\n        3'd7: current_char = char_7;\n        default: current_char = 5'd0;\n    endcase\nend\n\n// State machine\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 4'd0;\n        char_idx <= 3'd0;\n        meow_idx <= 2'd0;\n        min_result <= 4'd15;\n        for (i = 0; i < 5; i = i + 1) begin\n            dp_prev[i] <= 4'd0;\n            dp_curr[i] <= 4'd0;\n        end\n    end else begin\n        case(state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    dp_prev[0] <= 4'd0;\n                    dp_prev[1] <= 4'd1;\n                    dp_prev[2] <= 4'd2;\n                    dp_prev[3] <= 4'd3;\n                    dp_prev[4] <= 4'd4;\n                    min_result <= 4'd4;\n                    char_idx <= 3'd0;\n                    meow_idx <= 2'd0;\n                    if (len == 3'd0) begin\n                        result <= 4'd4;\n                        state <= FINISH;\n                    end else begin\n                        state <= INIT;\n                    end\n                end\n            end\n            \n            INIT: begin\n                state <= COMPUTE;\n            end\n            \n            COMPUTE: begin\n                if (char_idx < len && char_idx < 3'd8) begin\n                    case(meow_idx)\n                        2'd0: begin\n                            dp_curr[0] <= char_idx + 4'd1;\n                            meow_idx <= 2'd1;\n                        end\n                        \n                        2'd1: begin\n                            dp_curr[1] <= min3(\n                                dp_prev[0] + ((current_char == CHAR_M) ? 4'd0 : 4'd1),\n                                dp_prev[1] + 4'd1,\n                                dp_curr[0] + 4'd1\n                            );\n                            meow_idx <= 2'd2;\n                        end\n                        \n                        2'd2: begin\n                            dp_curr[2] <= min3(\n                                dp_prev[1] + ((current_char == CHAR_E) ? 4'd0 : 4'd1),\n                                dp_prev[2] + 4'd1,\n                                dp_curr[1] + 4'd1\n                            );\n                            meow_idx <= 2'd3;\n                        end\n                        \n                        2'd3: begin\n                            dp_curr[3] <= min3(\n                                dp_prev[2] + ((current_char == CHAR_O) ? 4'd0 : 4'd1),\n                                dp_prev[3] + 4'd1,\n                                dp_curr[2] + 4'd1\n                            );\n                            dp_curr[4] <= min3(\n                                dp_prev[3] + ((current_char == CHAR_W) ? 4'd0 : 4'd1),\n                                dp_prev[4] + 4'd1,\n                                dp_curr[3] + 4'd1\n                            );\n                            \n                            if (dp_curr[4] < min_result) min_result <= dp_curr[4];\n                            \n                            dp_prev[0] <= dp_curr[0];\n                            dp_prev[1] <= dp_curr[1];\n                            dp_prev[2] <= dp_curr[2];\n                            dp_prev[3] <= dp_curr[3];\n                            dp_prev[4] <= dp_curr[4];\n                            \n                            char_idx <= char_idx + 3'd1;\n                            meow_idx <= 2'd0;\n                        end\n                    endcase\n                end else begin\n                    state <= FINISH;\n                end\n            end\n            \n            FINISH: begin\n                result <= min_result;\n                done <= 1'b1;\n                state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nfunction [3:0] min3;\n    input [3:0] a, b, c;\n    reg [3:0] temp;\n    begin\n        temp = (a < b) ? a : b;\n        min3 = (temp < c) ? temp : c;\n    end\nendfunction\n\nendmodule